-- Runtime repair for missing admin RPCs and broken balance operations.
create or replace function public.admin_balance_operation(p_amount numeric,p_description text,p_player_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare old numeric; new numeric; a numeric:=coalesce(p_amount,0); st text; begin if not public.is_bank_admin() then raise exception 'Недостаточно прав'; end if; if a=0 then raise exception 'Сумма не может быть нулевой'; end if; select coalesce(balance,0),lower(coalesce(status,'active')) into old,st from public.profiles where id=p_player_id for update; if not found then raise exception 'Игрок не найден'; end if; if st<>'active' then raise exception 'Игрок заморожен или заблокирован'; end if; new:=old+a; if new<0 then raise exception 'Недостаточно средств у игрока'; end if; update public.profiles set balance=new where id=p_player_id; insert into public.transactions(from_user,to_user,amount,type,description) values(case when a<0 then p_player_id else auth.uid() end,case when a>0 then p_player_id else auth.uid() end,abs(a),case when a>0 then 'deposit' else 'withdraw' end,coalesce(nullif(trim(p_description),''),'Административная операция')); return jsonb_build_object('success',true,'amount',a,'old_balance',old,'new_balance',new); end; $$;
grant execute on function public.admin_balance_operation(numeric,text,uuid) to authenticated;

create or replace function public.admin_update_player_profile(p_player_id uuid,p_full_name text,p_birth_date date,p_passport_number text,p_username text) returns jsonb language plpgsql security definer set search_path=public as $$ begin if not public.is_bank_admin() then raise exception 'Недостаточно прав'; end if; update public.profiles set full_name=coalesce(nullif(trim(p_full_name),''),full_name),birth_date=p_birth_date,passport_number=coalesce(nullif(trim(p_passport_number),''),passport_number),username=coalesce(nullif(trim(p_username),''),username) where id=p_player_id; if not found then raise exception 'Игрок не найден'; end if; return jsonb_build_object('success',true,'player_id',p_player_id); end; $$;
grant execute on function public.admin_update_player_profile(uuid,text,date,text,text) to authenticated;
notify pgrst,'reload schema';